CREATE TABLE events (
		device_id TEXT    NOT NULL,
		seq       INTEGER NOT NULL,
		hlc       INTEGER NOT NULL,
		actor     TEXT    NOT NULL,
		kind      TEXT    NOT NULL,
		payload   BLOB,
		PRIMARY KEY (device_id, seq)
	) WITHOUT ROWID;
	CREATE INDEX events_hlc ON events (hlc);
	CREATE INDEX events_kind ON events (kind, hlc);
